  // Deterministic small offset derived from a string seed — used to fuzz the
  // exact pin shown on the (buyer-facing) vehicle detail map, so the same
  // listing always shows the same approximate point instead of jumping
  // around on every render, while never revealing the real coordinate.
  function seededOffset(seedStr, magnitudeDeg) {
    let h = 0;
    const s = String(seedStr || "x");
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    const angle = ((h % 1000) / 1000) * Math.PI * 2;
    const radius = (((h >> 3) % 1000) / 1000) * magnitudeDeg;
    return [Math.cos(angle) * radius, Math.sin(angle) * radius];
  }

  // Turns a real lat/lng into a coarse, human-readable district label
  // relative to a reference point (typically the point the map first
  // centered on) — e.g. "شمال شرقی", "مرکز شهر". No reverse-geocoding
  // service involved; this keeps the same privacy-preserving "region only"
  // behavior the fake grid map used to provide, now driven by real
  // coordinates.
  function regionLabelFromLatLng(ref, lat, lng) {
    const dLat = lat - ref[0];
    const dLng = lng - ref[1];
    const THRESH = 0.025;
    const v = dLat > THRESH ? "شمال" : dLat < -THRESH ? "جنوب" : "";
    const h = dLng > THRESH ? "شرقی" : dLng < -THRESH ? "غربی" : "";
    if (!h && !v) return "مرکز شهر";
    if (h && v) return `${v} ${h}`;
    return h ? `${h} شهر` : `${v} شهر`;
  }

