  function carPanelDiagramSVG(selectedParts, interactive) {
    const list = Array.isArray(selectedParts) ? selectedParts : [];
    const byKey = new Map(list.map((d) => [d.key, d.status]));
    // Until the user picks their first part, a small guide finger glides over
    // the car and taps a few panels (with a ripple) to show it's interactive.
    const hintTaps = interactive && list.length === 0;
    const panelsMarkup = CAR_PANELS.map((p) => {
      const status = byKey.get(p.key);
      const info = status ? partStatusInfo(status) : null;
      const fill = info ? partStatusInfo(status).color + "8c" : "rgba(0,0,0,0.001)";
      const cls = "car-panel-shape" + (info ? " car-panel-selected" : "");
      const attrs = interactive
        ? ` data-action="openPartStatusPicker" data-panel="${p.key}" role="button" tabindex="0" aria-pressed="${!!info}" aria-label="${p.label}"`
        : "";
      const title = info ? `${p.label} — ${info.label}` : p.label;
      return `<path${attrs} class="${cls}"d="${p.d}" fill="${fill}" stroke="${info ? info.color : "transparent"}" stroke-width="4"><title>${title}</title></path>`;
    }).join("");
    return `<svg viewBox="0 0 1920 1080" class="w-full max-w-[420px] h-auto block" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
      <image href="${CAR_DIAGRAM_IMG}" xlink:href="${CAR_DIAGRAM_IMG}" x="0" y="0" width="1920" height="1080"/>
      ${panelsMarkup}
      ${hintTaps ? CAR_TAP_HINT_MARKUP : ""}
    </svg>`;
  }

  function buildDamageStepContent(f) {
    const selected = Array.isArray(f.damagedParts) ? f.damagedParts : [];
    const box = mountTemplate("tpl-sell-step-damage");
    box.querySelector('[data-slot="note"]').replaceWith(mountTemplate("tpl-sell-note-4"));
    setDynamicHTML(box.querySelector('[data-slot="diagram"]'), carPanelDiagramSVG(selected, true));
    const chips = box.querySelector('[data-slot="panel-chips"]');
    CAR_PANELS.forEach((p) => {
      const entry = selected.find((d) => d.key === p.key);
      const info = entry ? partStatusInfo(entry.status) : null;
      const chip = document.createElement("button");
      chip.type = "button";
      chip.dataset.action = "openPartStatusPicker";
      chip.dataset.panel = p.key;
      chip.setAttribute("aria-pressed", String(!!info));
      chip.className = "damage-chip" + (info ? " is-selected" : "");
      if (info) {
        chip.style.setProperty("--damage-chip-color", info.color);
        chip.textContent = `${p.label} — ${info.label}`;
      } else {
        chip.textContent = p.label;
      }
      chips.appendChild(chip);
    });
    const summary = box.querySelector('[data-slot="summary"]');
    summary.textContent = selected.length
      ? `${selected.length.toLocaleString()} قسمت ثبت شده.`
      : "اگر بدنه سالم است، این مرحله را رد کنید.";

    const trigger = box.querySelector('[data-slot="bodyConditionTrigger"]');
    if (trigger) {
      const info = bcondTriggerLabel(f.bodyConditionRating);
      trigger.classList.toggle("has-rating", info.hasRating);
      const sub = trigger.querySelector('[data-slot="bcondTriggerSub"]');
      if (sub) sub.textContent = info.hasRating ? info.text : "ثبت نشده";
      if (info.hasRating) {
        const level = bcondLevel(f.bodyConditionRating);
        trigger.style.setProperty("--bcond-color", level.color);
      }
    }
    return box;
  }

